// All Star, step 3: rewards. The store owner sees the quarter so far against the target (Bronze, Silver, Gold), the value
// covered by invoices and the counter pool per month and per person; counter staff see their own sales and share; the
// head office dashboard gets an All Star tab (counter staff, monthly reports, quarter against target per store).
// Database: stravik_as_owner(), stravik_as_counter(), stravik_as_hq().
const fs = require("fs");
function edit(file, pairs) {
  let s = fs.readFileSync(file, "utf8");
  for (const [from, to] of pairs) {
    const n = s.split(from).length - 1;
    if (n !== 1) { console.error(`${file}: expected the text once, found it ${n} times: ${from.slice(0, 70)}`); process.exit(1); }
    s = s.replace(from, () => to);
  }
  fs.writeFileSync(file, s);
  console.log(file + ": updated");
}
