{ const f = "assets/autobarn.css", s = fs.readFileSync(f, "utf8"); if (s.includes(".as-q{")) { console.error(f + ": already there"); process.exit(1); } fs.writeFileSync(f, s + "\n/* All Star: the quarter against the target */\n.as-q{margin:6px 0 18px;padding:16px 18px;background:var(--card);border:1px solid var(--line);border-left:4px solid var(--gold);border-radius:8px}\n.as-q p{margin:8px 0 0}\n.as-qh{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px 16px}\n.as-qh .ab-h{margin:0}\n.as-bar{position:relative;height:14px;margin:30px 0 6px;background:var(--paper);border:1px solid var(--line);border-radius:999px}\n.as-bar i{display:block;height:100%;background:var(--gold);border-radius:999px}\n.as-bar b{position:absolute;top:-6px;bottom:-6px;width:2px;background:var(--ink);opacity:.5}\n.as-bar b span{position:absolute;bottom:100%;left:50%;transform:translateX(-50%);margin-bottom:2px;font-size:12.5px;font-weight:600;color:var(--muted);white-space:nowrap}\n"); console.log(f + ": updated"); }
